'use strict';

function forecastPlain(value){return value&&typeof value==='object'&&!Array.isArray(value)}
function forecastInteger(value,fallback){return typeof value==='number'&&Number.isFinite(value)&&Number.isInteger(value)&&value>=0&&value<=10000?value:fallback}
function forecastMainItems(){return planItems.filter(function(item){return !components.some(function(component){return component.id===item.id})})}
function forecastComponentItems(){return planItems.filter(function(item){return components.some(function(component){return component.id===item.id})})}
// Aggregate sample records for the same service or whole weekend, at the same booking lead time.
const forecastInputs = {
 morgen: {
  booked: 64,
  history: [
   {period: 'week',  booked: 60, guests: 76, sold: {hamburger: 26, risotto: 28, kipsate: 22}},
   {period: 'month', booked: 70, guests: 84, sold: {hamburger: 36, risotto: 30, kipsate: 18}},
   {period: 'year',  booked: 62, guests: 80, sold: {hamburger: 34, risotto: 26, kipsate: 20}}
  ]
 },
 weekend: {
  booked: 176,
  history: [
   {period: 'week',  booked: 160, guests: 200, sold: {hamburger: 68, risotto: 76, kipsate: 56}},
   {period: 'month', booked: 176, guests: 230, sold: {hamburger: 96, risotto: 84, kipsate: 50}},
   {period: 'year',  booked: 192, guests: 230, sold: {hamburger: 100, risotto: 71, kipsate: 59}}
  ]
 }
};
function refreshForecastPeriod(period, record){
 const input=forecastInputs[period];
 const attendanceRows=input.history.filter(row=>forecastInteger(row.booked,null)!==null && forecastInteger(row.guests,null)!==null);
 const booked=attendanceRows.reduce((sum,row)=>sum+row.booked,0);
 const guests=attendanceRows.reduce((sum,row)=>sum+row.guests,0);
 const currentBookings=record.bookingReport?.booked ?? input.booked;
 record.baseGuests=booked ? Math.round(currentBookings*guests/booked) : currentBookings;
 record.guests=record.guestOverride===null ? record.baseGuests : record.guestOverride;
 record.automatic={};
 record.expected={};
 for(const item of planItems){
  const salesRows=input.history.filter(row=>forecastInteger(row.guests,0)>0 && forecastPlain(row.sold) && forecastInteger(row.sold[item.id],null)!==null);
  if(salesRows.length){
   const covers=salesRows.reduce((sum,row)=>sum+row.guests,0);
   const sold=salesRows.reduce((sum,row)=>sum+row.sold[item.id],0);
   record.automatic[item.id]=Math.round(record.guests*sold/covers);
  }
  record.expected[item.id]=record.dishOverrides[item.id] ?? record.automatic[item.id] ?? 0;
 }
}
function initForecast(storedForecast){
 const incoming=forecastPlain(storedForecast)?storedForecast:{};
 const clean={modelVersion:1,period:incoming.period==='weekend'?'weekend':'morgen',periods:{}};
 for(const period of ['morgen','weekend']){
  const source=incoming.periods && forecastPlain(incoming.periods[period]) ? incoming.periods[period] : {};
  const record={
   bookingReport:source.bookingReport ? Zenchef.activeRecord(source.bookingReport,period) : null,
   guestOverride:forecastInteger(source.guestOverride,null),
   dishOverrides:{},
   buffer:[0,5,10,15,20].includes(source.buffer)?source.buffer:0
  };
  // Older snapshots recorded the resolved sample and edits together. Only promote
  // differences from their original defaults to overrides, so a saved zero is kept.
  if(incoming.modelVersion!==1 && forecastPlain(source.expected)){
   const oldGuests=period==='morgen'?80:220;
   const oldDefaults=period==='morgen'?{hamburger:32,risotto:28,kipsate:20}:{hamburger:88,risotto:77,kipsate:55};
   const savedGuests=forecastInteger(source.guests,null);
   if(savedGuests!==null && savedGuests!==oldGuests)record.guestOverride=savedGuests;
   for(const item of planItems){
    const saved=forecastInteger(source.expected[item.id],null);
    if(saved!==null && saved!==(oldDefaults[item.id]??0))record.dishOverrides[item.id]=saved;
   }
  }else if(forecastPlain(source.dishOverrides)){
   for(const item of planItems){
    const saved=forecastInteger(source.dishOverrides[item.id],null);
    if(saved!==null)record.dishOverrides[item.id]=saved;
   }
  }
  refreshForecastPeriod(period,record);
  clean.periods[period]=record;
 }
 state.forecast=clean;
 forecastSyncLegacy();
 return clean;
}
function forecastRecord(){
 return state.forecast.periods[state.forecast.period];
}
function setForecastGuests(value){
 if(value!==null && forecastInteger(value,null)===null)return;
 const record=forecastRecord();
 record.guestOverride=value;
 refreshForecastPeriod(state.forecast.period,record);
}
function setForecastQuantity(id,value){
 if(!planItems.some(item=>item.id===id))return;
 const record=forecastRecord();
 if(value===null)delete record.dishOverrides[id];
 else if(forecastInteger(value,null)!==null)record.dishOverrides[id]=value;
 else return;
 refreshForecastPeriod(state.forecast.period,record);
}
function forecastSyncLegacy(){
 const record=state.forecast.periods[state.forecast.period];
 state.mode='keukenlijst';state.covers=record.guests;state.buffer=record.buffer;
 state.manual=Object.fromEntries(planItems.map(function(item){return [item.id,record.expected[item.id]||0]}));
}
function forecastQuantity(item){const record=forecastRecord();return Math.ceil((record.expected[item.id]||0)*(1+record.buffer/100)-1e-9)}
function forecastSummary(){
 const record=forecastRecord(),main=forecastMainItems(),loose=forecastComponentItems();
 return {period:state.forecast.period,label:periodLabel(),guests:record.guests,expectedSales:main.reduce(function(sum,item){return sum+(record.expected[item.id]||0)},0),prepPortions:main.reduce(function(sum,item){return sum+forecastQuantity(item)},0),componentQty:loose.reduce(function(sum,item){return sum+forecastQuantity(item)},0),buffer:record.buffer,recipeCount:planItems.filter(function(item){return forecastQuantity(item)>0}).length};
}

.forecast-guests > label { color: var(--muted); font-size: 12px; font-weight: 650; }
.forecast-guests > small, .forecast-dish-source { color: var(--muted); font-size: 12px; }
.forecast-help { line-height: 1.55; }
.forecast-adjustment { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 12px; color: var(--green); margin-bottom: 5px; }
.forecast-restore { background: transparent; color: var(--green); text-decoration: underline; text-underline-offset: 3px; padding: 5px 0; font-weight: 650; }
.forecast-sources { background: white; border: 1px solid var(--line); border-radius: 9px; margin: -8px 0 20px; padding: 12px 18px; }
.forecast-sources summary { color: var(--green); cursor: pointer; }
.forecast-sources summary small { margin-left: 8px; font-size: 12px; color: var(--muted); }
.forecast-sources p { max-width: 75ch; margin: 12px 0 6px; }
.forecast-sources table { width: 100%; border-collapse: collapse; font-size: 13px; font-variant-numeric: tabular-nums; white-space: normal; }
.forecast-sources caption { text-align: left; padding: 10px 0; font-weight: bold; color: var(--green); }
.forecast-sources th, .forecast-sources td { padding: 7px 5px; text-align: right; border-bottom: 1px solid var(--line); white-space: normal; }
.forecast-sources th[scope=row] { width: 44%; text-align: left; font-weight: 500; }
.forecast-dish-source { display: block; margin-top: 4px; }
.forecast-dish-source .forecast-restore { margin-left: 8px; }
@media (max-width: 500px) {
  .forecast-sources { padding: 12px; }
  .forecast-sources table { table-layout: fixed; font-size: 12px; overflow-wrap: anywhere; }
  .forecast-sources thead td { width: 43%; }
  .forecast-sources th, .forecast-sources td { padding: 6px 3px; }
  .forecast-sources summary small { display: inline-block; }
}

/* Display the sources and adjustments for the selected service. */
const forecastViewCopy = document.documentElement.lang === 'en' ? {
  period: 'Your plan for', tomorrow: 'Tomorrow', weekend: 'Weekend', wholeWeekend: 'Total for the entire weekend',
  wholeDay: 'Total for tomorrow', guests: 'Expected guests', dishes: 'Dishes expected', guestUnit: 'guests',
  margin: 'Extra margin', extra: 'Prepare extra', marginHelp: 'Applied to dishes and separate components. Prep quantities round up to whole portions.',
  base: 'Forecast', adjusted: 'Adjusted', reset: 'Restore forecast',
  help: 'For an event or a quieter service, change the expected guests. Dish quantities update with attendance unless you have entered a quantity for that dish.',
  restored: 'Guest forecast restored.', saved: 'Guest count saved. Preparation and draft orders have been recalculated.',
  invalid: 'Enter a whole number of guests between 0 and 10,000.',
  sources: 'How the forecast is calculated', sample: 'Sample data', booked: 'guests booked in Zenchef',
  sourceIntro: 'OrderCrew estimates attendance using current bookings and the historical ratio of guests served to guests booked. Dish forecasts use the number sold per guest served.',
  day: 'Comparison for the same weekday', days: 'Comparison for the entire weekend',
  week: 'Last week', month: 'Last month', year: 'Last year', historicalBooked: 'Guests booked¹', historicalActual: 'Guests served',
  lead: '¹ Bookings are compared at the same lead time before service. The historical figures are examples.',
  forecast: 'Forecast', manual: 'Your quantity', manualItem: 'Enter the quantity', noHistory: 'No sales history for this dish',
  sold: 'Sold', restoreDish: 'Restore forecast for'
} : {
  period: 'Je planning voor', tomorrow: 'Morgen', weekend: 'Weekend', wholeWeekend: 'Totaal voor het hele weekend',
  wholeDay: 'Totaal voor morgen', guests: 'Verwachte opkomst', dishes: 'Gerechten verwacht', guestUnit: 'gasten',
  margin: 'Extra marge', extra: 'Meer voorbereiden', marginHelp: 'Geldt voor gerechten en losse bereidingen. De keukenlijst rondt naar boven af op hele porties.',
  base: 'Voorspeld', adjusted: 'Bijgesteld', reset: 'Herstel voorspelling',
  help: 'Verwacht je door een evenement of een rustige dienst een andere opkomst? Pas het gastenaantal aan. De gerechten rekenen mee, behalve als je voor een gerecht zelf een aantal hebt ingevuld.',
  restored: 'De voorspelde opkomst is hersteld.', saved: 'Opkomst opgeslagen. De keukenlijst en het bestelvoorstel zijn herberekend.',
  invalid: 'Vul een heel aantal gasten tussen 0 en 10.000 in.',
  sources: 'Hoe is dit voorspeld?', sample: 'Voorbeeldgegevens', booked: 'gasten gereserveerd in Zenchef',
  sourceIntro: 'OrderCrew schat de opkomst uit de huidige reserveringen en de eerdere verhouding tussen gereserveerde en werkelijk ontvangen gasten. De verkoop per ontvangen gast bepaalt de verwachting per gerecht.',
  day: 'Vergelijking voor dezelfde weekdag', days: 'Vergelijking voor het hele weekend',
  week: 'Vorige week', month: 'Vorige maand', year: 'Vorig jaar', historicalBooked: 'Gereserveerde gasten¹', historicalActual: 'Ontvangen gasten',
  lead: '¹ We vergelijken de reserveringsstand op hetzelfde moment vóór de service. De historische aantallen zijn voorbeelden.',
  forecast: 'Voorspeld', manual: 'Eigen aantal', manualItem: 'Aantal zelf invullen', noHistory: 'Geen verkoopgeschiedenis voor dit gerecht',
  sold: 'Verkocht', restoreDish: 'Herstel voorspelling voor'
};

function forecastControls() {
  const copy = forecastViewCopy;
  const record = forecastRecord();
  const period = state.forecast.period;
  const adjusted = record.guestOverride !== null;
  const booked = record.bookingReport?.booked ?? forecastInputs[period].booked;
  const periodSwitch = ['morgen', 'weekend'].map(key =>
    `<button type="button" data-forecast-period="${key}" aria-pressed="${key === period}">${key === 'morgen' ? copy.tomorrow : copy.weekend}</button>`
  ).join('');
  const marginOptions = [0, 5, 10, 15, 20].map(value =>
    `<option value="${value}"${record.buffer === value ? ' selected' : ''}>${value}%</option>`
  ).join('');
  return `<section class="forecast-controls" aria-label="${copy.period}">
    <div class="forecast-period"><span class="forecast-label">${copy.period}</span>
      <div class="forecast-switch" role="group" aria-label="${copy.period}">${periodSwitch}</div>
      <small>${period === 'weekend' ? copy.wholeWeekend : copy.wholeDay}</small></div>
    <div class="forecast-guests"><label for="guest-estimate">${copy.guests}</label>
      <div class="forecast-number-field"><input id="guest-estimate" data-forecast-guests type="number" min="0" max="10000" step="1" inputmode="numeric"
        aria-describedby="guest-basis forecastGuestHelp" value="${record.guests}"><span>${copy.guestUnit}</span></div>
      <small id="guest-basis">${n(booked)} ${copy.booked}</small></div>
    <div class="forecast-expectation"><strong>${n(forecastSummary().expectedSales)}</strong><span>${copy.dishes}</span></div>
    <details class="forecast-options"><summary>${copy.margin}${record.buffer ? ' · ' + record.buffer + '%' : ''}</summary>
      <label><span>${copy.extra}</span><select data-forecast-buffer>${marginOptions}</select></label><small>${copy.marginHelp}</small></details>
    <div id="forecastGuestHelp" class="forecast-help">${adjusted ?
      `<div class="forecast-adjustment"><strong>${copy.base} ${n(record.baseGuests)} · ${copy.adjusted} ${n(record.guests)}</strong>
       <button type="button" class="forecast-restore" data-forecast-reset-guests>${copy.reset}</button></div>` : ''}${copy.help}</div>
  </section>`;
}

function forecastSources() {
  const copy = forecastViewCopy;
  const period = state.forecast.period;
  const history = forecastInputs[period].history;
  const headers = history.map(row => `<th scope="col">${copy[row.period]}</th>`).join('');
  function row(label, readValue) {
    return `<tr><th scope="row">${label}</th>${history.map(period => {
      const value = readValue(period);
      return `<td>${Number.isFinite(value) ? n(value) : '·'}</td>`;
    }).join('')}</tr>`;
  }
  const rows = [
    row(copy.historicalBooked, period => period.booked),
    row(copy.historicalActual, period => period.guests)
  ];
  forecastMainItems().filter(item => history.some(period => Number.isFinite(period.sold[item.id]))).forEach(item => {
    const name = document.documentElement.lang === 'en' ? ocName(item) : item.name;
    rows.push(row(copy.sold + ' · ' + esc(name), period => period.sold[item.id]));
  });
  return `<details class="forecast-sources"><summary><strong>${copy.sources}</strong><small>${forecastRecord().bookingReport ? (document.documentElement.lang === 'en' ? 'Imported bookings · sample history' : 'Ingelezen reserveringen · voorbeeldhistorie') : copy.sample}</small></summary>
    <p>${copy.sourceIntro}</p><table><caption>${period === 'morgen' ? copy.day : copy.days}</caption>
      <thead><tr><td></td>${headers}</tr></thead><tbody>${rows.join('')}</tbody></table>
    <p><small>${copy.lead}</small></p></details>`;
}

function forecastDishSource(item, isComponent) {
  const copy = forecastViewCopy;
  const record = forecastRecord();
  const hasHistory = Object.hasOwn(record.automatic, item.id);
  if (isComponent) return '';
  if (!hasHistory) return `<span class="forecast-dish-source">${copy.noHistory} · ${copy.manualItem}</span>`;
  const predicted = n(record.automatic[item.id]);
  if (!Object.hasOwn(record.dishOverrides, item.id)) return `<span class="forecast-dish-source">${copy.forecast} · ${predicted}</span>`;
  const name = document.documentElement.lang === 'en' ? ocName(item) : item.name;
  return `<span class="forecast-dish-source"><strong>${copy.manual}</strong> · ${copy.forecast} ${predicted}
    <button type="button" class="forecast-restore" data-forecast-reset-quantity="${esc(item.id)}"
      aria-label="${copy.restoreDish} ${esc(name)}">${copy.reset}</button></span>`;
}

function bindGuestAdjustment() {
  const copy = forecastViewCopy;
  const input = document.querySelector('[data-forecast-guests]');
  if (!input) return;
  const commit = (value, message) => {
    setForecastGuests(value);
    forecastCommitted(message);
    document.querySelector('[data-forecast-guests]')?.focus({preventScroll: true});
  };
  input.onchange = () => {
    const value = input.valueAsNumber;
    if (forecastInteger(value, -1) === -1) {
      input.value = forecastRecord().guests;
      notify(copy.invalid);
      return;
    }
    if (value !== forecastRecord().guests) commit(value, copy.saved);
  };
  const reset = document.querySelector('[data-forecast-reset-guests]');
  if (reset) reset.onclick = () => commit(null, copy.restored);
}

'use strict';

// Bridge between the inventory ledger and the original demo entry points.
const InventoryStock = (() => {
  const en = document.documentElement.lang === 'en';
  const t = (nl, english) => en ? english : nl;
  const name = product => en ? ocName(product) : product.name;
  const unit = product => en ? ocUnit(product.unit) : product.unit;
  const quantity = (product, value) => n(value, 3) + ' ' + unit(product);
  function load(previous) {
    const today = InventoryPlan.today();
    state.inventory = InventoryPlan.init(previous?.inventory, products, state.stock, {fresh: !previous, today});
    // Two labelled batches in the sample kitchen make the first thaw task visible.
    // Existing kitchen counts keep their original details on upgrade.
    if (!previous) {
      const chicken = products.find(p => p.id === 'kip');
      if (chicken && state.stock[chicken.id] === 4) {
        const tomorrow = InventoryPlan.addDays(today, 1);
        InventoryPlan.setProduct(state.inventory, chicken, {window: 'inherit', lots: [
          {id: 'k01', label: 'K-01', qty: 2, storage: 'ready', availableFrom: today, useBy: tomorrow},
          {id: 'k02', label: 'K-02', qty: 2, storage: 'frozen', availableFrom: today, useBy: tomorrow, thawDays: 1}
        ]});
      }
    }
    for (const product of products) sync(product);
  }
  function sync(product) {
    state.stock[product.id] = InventoryPlan.total(state.inventory.products[product.id]);
  }
  function rows(m) {
    const matches = products.filter(p =>
      name(p).toLowerCase().includes(searchValue.toLowerCase()) &&
      (stockCategory === 'alle' || p.category === stockCategory) &&
      (!lowOnly || m.inventory[p.id].shortage > 0));
    return matches.map(p => {
      const plan = m.inventory[p.id];
      const needs = plan.shortage > 0;
      const status = needs ? t('Aanvullen', 'Replenish') : t('Voldoende', 'Enough');
      return `<tr><td><div class="mini-product"><span class="produce">${icon(p.icon,19)}</span>
        <div><strong>${esc(name(p))}</strong><span class="subline">${money(p.price)} / ${esc(unit(p))} · ${categories[p.category]}</span>
        ${InventoryView.stockButton(p)}</div></div></td>
        <td><div class="stock-field"><input type="number" inputmode="decimal" min="0" max="10000" step="${p.unit === 'st' ? 1 : .001}"
          value="${state.stock[p.id]}" data-stock="${esc(p.id)}" aria-label="${t('Getelde voorraad', 'Counted stock')} ${esc(name(p))}"><span>${esc(unit(p))}</span></div></td>
        <td>${quantity(p,plan.need)}<small class="subline">${esc(InventoryView.periodInfo(plan))}</small>
          <span data-mobile-status="${esc(p.id)}" class="mobile-status ${needs?'needs-stock':''}">${status}</span></td>
        <td><span data-status="${esc(p.id)}" class="tag ${needs?'warn':''}">${status}</span></td>
        <td class="optional">${InventoryView.stockHint(p,plan)}</td></tr>`;
    }).join('') || '<tr><td colspan="5" class="empty">'+t('Geen producten gevonden.', 'No products found.')+'</td></tr>';
  }
  function recount(input) {
    const p = products.find(p => p.id === input.dataset.stock);
    const value = input.valueAsNumber;
    if (!p) return;
    const old = state.stock[p.id];
    if (!productQuantityValid(p,value,0,10000)) {
      input.value = old;
      notify(t('Controleer de hoeveelheid en de eenheid.', 'Check the quantity and unit.'));
      return;
    }
    if (value === old) return;
    try {
      InventoryPlan.recount(state.inventory,p,value);
    } catch {
      input.value = old;
      InventoryView.open(p.id);
      notify(t('Pas de hoeveelheid aan bij de juiste partij.', 'Update the quantity on the relevant batch.'));
      return;
    }
    sync(p);
    state.counts[p.id]++;
    save(); render();
    document.querySelector('[data-stock="'+p.id+'"]')?.focus({preventScroll:true});
    notify(t('Voorraad en bestelvoorstel bijgewerkt.', 'Stock and draft order updated.'));
  }
  function bindWaste() {
    const form = document.querySelector('#wasteForm');
    if (!form) return;
    const productField = form.querySelector('#wasteProduct');
    const qtyField = form.querySelector('#wasteQty');
    const lotField = form.querySelector('#wasteLot');
    const product = () => products.find(p => p.id === productField.value);
    function limits() {
      const p = product();
      const lot = state.inventory.products[p.id].lots.find(x => x.id === lotField.value);
      const available = lot ? lot.qty : state.stock[p.id];
      qtyField.max = available;
      qtyField.min = qtyField.step = p.unit === 'st' ? 1 : .001;
      form.querySelector('#qtyLabel').textContent = t('Hoeveelheid','Quantity') + ' (' + unit(p) + ')';
      document.getElementById('availableStock').textContent = t('Geteld','Counted') + ' · ' + quantity(p, available);
    }
    function fillLots() {
      const p = product();
      const choices = state.inventory.products[p.id].lots.filter(x => x.qty > 0);
      lotField.replaceChildren();
      if (choices.length !== 1) lotField.add(new Option(t('Kies een partij','Choose a batch'), ''));
      for (const [index,lot] of choices.entries()) {
        const date = lot.useBy ? ' · '+lot.useBy : '';
        const location = lot.storage === 'frozen' ? t('vriezer','freezer') : t('gebruiksklaar','ready');
        lotField.add(new Option((lot.label || t('Partij ','Batch ')+(index+1)) + ' · ' + location + ' · ' + quantity(p,lot.qty) + date,lot.id));
      }
      lotField.required = true;
      limits();
    }
    productField.onchange = fillLots;
    lotField.onchange = limits;
    fillLots();
    form.onsubmit = event => {
      event.preventDefault();
      const p = product();
      const qty = qtyField.valueAsNumber;
      if (!lotField.value || !productQuantityValid(p,qty,.001,Number(qtyField.max))) {
        notify(t('Controleer de partij en hoeveelheid.','Check the batch and quantity.'));
        return;
      }
      let fragments;
      try { fragments = InventoryPlan.removeWaste(state.inventory,p,qty,lotField.value); }
      catch { notify(t('Deze partij heeft onvoldoende voorraad.','This batch has insufficient stock.')); return; }
      sync(p);
      state.waste.push({id:crypto.randomUUID(),product:p.id,qty,reason:form.querySelector('#wasteReason').value,count:state.counts[p.id],fragments});
      save(); render(); notify(t('Verspilling afgeboekt op deze partij.','Waste deducted from the selected batch.'));
    };
  }
  function undoWaste(w) {
    const p = products.find(product => product.id === w.product);
    try {
      if (Array.isArray(w.fragments) && w.fragments.length) InventoryPlan.restoreWaste(state.inventory,p,w.fragments);
      else InventoryPlan.restoreLegacyWaste(state.inventory,p,w.qty);
      sync(p);
      return true;
    } catch {
      notify(t('Herstellen is niet mogelijk met deze partijtelling. Controleer de voorraad.','This batch count prevents restoring the entry. Check your stock.'));
      return false;
    }
  }
  return {load,rows,recount,bindWaste,undoWaste};
})();

/* The kitchen enters dates and thaw times. Planning only allocates quantities. */
const InventoryPlan = (() => {
  'use strict';
  const windows = ['inherit', 'day', 'weekend', 'week'];
  const millisPerDay = 86400000;
  const units = n => Math.round(n * 1000);
  const quantity = n => n / 1000;

  function check(condition, code) {
    if (!condition) throw Object.assign(new Error(code), {code});
  }
  function today(clock = new Date()) {
    return [clock.getFullYear(), String(clock.getMonth() + 1).padStart(2, '0'),
      String(clock.getDate()).padStart(2, '0')].join('-');
  }
  // Dates are civil days in the kitchen's locale; UTC arithmetic avoids DST jumps.
  function validDate(value) {
    if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
    const date = new Date(value + 'T00:00:00Z');
    return Number.isFinite(date.getTime()) && date.toISOString().slice(0, 10) === value;
  }
  function addDays(date, days) {
    return new Date(Date.parse(date + 'T00:00:00Z') + days * millisPerDay).toISOString().slice(0, 10);
  }
  function weekday(date) { return new Date(date + 'T00:00:00Z').getUTCDay(); }
  function validQuantity(product, qty) {
    return Number.isFinite(qty) && qty >= 0 && qty <= 10000 &&
      (product.unit === 'st' ? Number.isInteger(qty) : Math.abs(units(qty) - qty * 1000) < 1e-7);
  }
  function normalizeLot(product, lot) {
    check(lot && /^[a-zA-Z0-9_-]{1,80}$/.test(lot.id) && typeof lot.id === 'string', 'id');
    const label = lot.label ?? '';
    check(typeof label === 'string' && label.trim().length <= 80, 'label');
    check(validQuantity(product, lot.qty), 'quantity');
    check(lot.storage === 'ready' || lot.storage === 'frozen', 'storage');
    const availableFrom = lot.availableFrom ?? '';
    const useBy = lot.useBy ?? '';
    check((availableFrom === '' || validDate(availableFrom)) && (useBy === '' || validDate(useBy)), 'date');
    check(!availableFrom || !useBy || availableFrom <= useBy, 'dateOrder');
    const thawDays = lot.storage === 'frozen' ? (lot.thawDays ?? null) : null;
    check(thawDays === null || (Number.isInteger(thawDays) && thawDays >= 0 && thawDays <= 365), 'thawDays');
    const result = {id: lot.id, label: label.trim(), qty: quantity(units(lot.qty)), storage: lot.storage, availableFrom, useBy, thawDays};
    if (lot.storage === 'ready' && lot.thawStarted) {
      check(validDate(lot.thawStarted) && lot.thawStarted <= availableFrom, 'thawStart');
      result.thawStarted = lot.thawStarted;
    }
    return result;
  }
  function total(entry) { return quantity(entry.lots.reduce((sum, lot) => sum + units(lot.qty), 0)); }
  function normalizeEntry(product, entry) {
    check(entry && windows.includes(entry.window), 'window');
    check(Array.isArray(entry.lots), 'lots');
    check(entry.lots.length <= 100, 'limit');
    const lots = entry.lots.map(lot => normalizeLot(product, lot)).filter(lot => lot.qty > 0);
    check(new Set(lots.map(lot => lot.id)).size === lots.length, 'duplicate');
    const result = {window: entry.window, lots};
    check(total(result) <= 10000, 'total');
    return result;
  }
  function setProduct(inventory, product, entry) {
    const next = normalizeEntry(product, entry);
    inventory.products[product.id] = next;
    return total(next);
  }
  function undatedLot(qty, id = 'count') {
    return {id, label: '', qty, storage: 'ready', availableFrom: '', useBy: '', thawDays: null};
  }
  function init(saved, products, stockTotals, options = {}) {
    const date = options.today || today();
    const result = {version: 1, products: {}};
    for (const product of products) {
      const entry = saved?.version === 1 ? saved.products?.[product.id] : undefined;
      if (entry !== undefined) {
        try { setProduct(result, product, entry); }
        catch {
          // Damaged lot records must never silently become usable, undated stock.
          result.products[product.id] = {window: 'inherit', lots: []};
        }
        continue;
      }
      const qty = stockTotals?.[product.id] ?? product.stock;
      const lots = [];
      if (validQuantity(product, qty) && qty > 0) {
        const lot = undatedLot(qty);
        if (options.fresh && product.soon) lot.useBy = date;
        lots.push(lot);
      }
      setProduct(result, product, {window: 'inherit', lots});
    }
    return result;
  }
  function recount(inventory, product, qty) {
    check(validQuantity(product, qty), 'quantity');
    const entry = inventory.products[product.id];
    if (qty === total(entry)) return qty;
    check(entry.lots.length <= 1, 'splitCount');
    const lot = entry.lots.length ? {...entry.lots[0], qty} : undatedLot(qty);
    return setProduct(inventory, product, {window: entry.window, lots: qty ? [lot] : []});
  }
  function expiryOrder(a, b) {
    const dateA = a.useBy || '9999-12-31';
    const dateB = b.useBy || '9999-12-31';
    return dateA.localeCompare(dateB) || a.id.localeCompare(b.id);
  }
  function startThaw(inventory, product, task, date = today()) {
    check(task && validDate(date) && task.start === date && validDate(task.use), 'thawStart');
    const entry = inventory.products[product.id];
    const source = entry.lots.find(lot => lot.id === task.lotId);
    check(source?.storage === 'frozen' && source.thawDays !== null && source.useBy, 'storage');
    check((!source.availableFrom || source.availableFrom <= date) && task.use <= source.useBy &&
      addDays(date, source.thawDays) === task.use, 'thawDate');
    check(validQuantity(product, task.qty) && task.qty > 0 && task.qty <= source.qty, 'quantity');

    const started = {...source, qty: task.qty, storage: 'ready', availableFrom: task.use, thawDays: null, thawStarted: date};
    const remaining = quantity(units(source.qty) - units(task.qty));
    const lots = entry.lots.slice();
    const index = lots.indexOf(source);
    if (remaining) {
      let serial = 1;
      do { started.id = 'thaw-' + task.use + '-' + serial++; } while (lots.some(lot => lot.id === started.id));
      lots.splice(index, 1, {...source, qty: remaining}, started);
    } else lots[index] = started;
    return setProduct(inventory, product, {window: entry.window, lots});
  }
  function removeWaste(inventory, product, qty, lotId) {
    const entry = inventory.products[product.id];
    check(qty > 0 && validQuantity(product, qty), 'quantity');
    const lots = entry.lots.map(lot => ({...lot}));
    const candidates = (lotId ? lots.filter(lot => lot.id === lotId) : lots.slice()).sort(expiryOrder);
    let left = units(qty);
    const removed = [];
    for (const lot of candidates) {
      if (!left) break;
      const take = Math.min(left, units(lot.qty));
      removed.push({...lot, qty: quantity(take)});
      lot.qty = quantity(units(lot.qty) - take);
      left -= take;
    }
    check(left === 0, 'quantity');
    setProduct(inventory, product, {window: entry.window, lots});
    return removed;
  }
  function restoreWaste(inventory, product, fragments) {
    check(Array.isArray(fragments) && fragments.length > 0, 'lots');
    const entry = inventory.products[product.id];
    const lots = entry.lots.map(lot => ({...lot}));
    for (const fragment of fragments) {
      const piece = normalizeLot(product, fragment);
      const found = lots.find(lot => lot.id === piece.id);
      if (found) {
        check(['label', 'storage', 'availableFrom', 'useBy', 'thawDays', 'thawStarted'].every(k => found[k] === piece[k]), 'changed');
        found.qty = quantity(units(found.qty) + units(piece.qty));
      } else lots.push(piece);
    }
    return setProduct(inventory, product, {window: entry.window, lots});
  }
  function restoreLegacyWaste(inventory, product, qty) {
    const entry = inventory.products[product.id];
    const match = entry.lots.find(lot => lot.storage === 'ready' && !lot.label && !lot.availableFrom && !lot.useBy);
    let suffix = 0;
    while (!match && entry.lots.some(lot => lot.id === 'legacy-' + suffix)) suffix++;
    return restoreWaste(inventory, product, [undatedLot(qty, match?.id || 'legacy-' + suffix)]);
  }

  function windowDates(window, date) {
    const first = addDays(date, 1);
    if (window === 'day') return [first];
    if (window === 'week') return Array.from({length: 7}, (_, i) => addDays(first, i));
    const saturday = addDays(first, (6 - weekday(first) + 7) % 7);
    return [saturday, addDays(saturday, 1)];
  }
  function recipeDemand(products, items, record, split) {
    const result = Object.fromEntries(products.map(p => [p.id, 0]));
    for (const item of items) {
      const portions = Math.ceil((record.expected[item.id] || 0) * (1 + record.buffer / 100) - 1e-9);
      let count = portions;
      if (split === 'saturday') count = Math.ceil(portions / 2);
      if (split === 'sunday') count = Math.floor(portions / 2);
      for (const [id, perPortion] of Object.entries(item.recipe)) {
        if (Object.hasOwn(result, id) && Number.isFinite(perPortion) && perPortion >= 0) result[id] += count * perPortion;
      }
    }
    for (const id of Object.keys(result)) result[id] = units(result[id]);
    return result;
  }

  // Allocate to each service once. Try usable ready stock before opening a frozen
  // batch. An earlier allocation may be swapped if another lot can fulfil it.
  // E.g. a frozen batch expiring Saturday can free a chilled lot for Sunday.
  function allocate(lots, timeline, date) {
    const sorted = [...lots].sort(expiryOrder);
    const free = sorted.map(lot => units(lot.qty));
    const assigned = timeline.map(() => sorted.map(() => 0));
    const candidates = timeline.map(day => sorted.flatMap((lot, index) => {
      if ((lot.useBy && lot.useBy < day.date) || (lot.availableFrom && lot.availableFrom > day.date)) return [];
      if (lot.storage === 'frozen') {
        if (lot.thawDays === null || !lot.useBy) return [];
        const start = addDays(day.date, -lot.thawDays);
        if (start < date || (lot.availableFrom && start < lot.availableFrom)) return [];
      }
      return [index];
    }));
    function findPath(day, storage, visitedDays, visitedLots) {
      if (visitedDays.has(day)) return null;
      visitedDays.add(day);
      const direct = candidates[day].find(lot =>
        !visitedLots.has(lot) && free[lot] > 0 && sorted[lot].storage === storage);
      if (direct !== undefined) return [{day, lot: direct}];
      for (const lot of candidates[day]) {
        if (visitedLots.has(lot)) continue;
        visitedLots.add(lot);
        for (let other = 0; other < timeline.length; other++) {
          if (!assigned[other][lot]) continue;
          const alternate = findPath(other, storage, visitedDays, visitedLots);
          if (alternate) return [{day, lot}, ...alternate];
        }
      }
      return null;
    }
    for (let day = 0; day < timeline.length; day++) {
      let remaining = timeline[day].need;
      while (remaining > 0) {
        const path = findPath(day, 'ready', new Set(), new Set()) || findPath(day, 'frozen', new Set(), new Set());
        if (!path) break;
        const last = path[path.length - 1];
        let take = Math.min(remaining, free[last.lot]);
        for (let i = 1; i < path.length; i++) take = Math.min(take, assigned[path[i].day][path[i - 1].lot]);
        for (let i = 0; i < path.length; i++) {
          assigned[path[i].day][path[i].lot] += take;
          if (i) assigned[path[i].day][path[i - 1].lot] -= take;
        }
        free[last.lot] -= take;
        remaining -= take;
      }
    }
    return {sorted, assigned};
  }

  function build(products, items, forecast, inventory, date = today()) {
    const tomorrow = addDays(date, 1);
    const daily = recipeDemand(products, items, forecast.periods.morgen);
    const sat = recipeDemand(products, items, forecast.periods.weekend, 'saturday');
    const sun = recipeDemand(products, items, forecast.periods.weekend, 'sunday');
    const result = {};
    for (const product of products) {
      const entry = inventory.products[product.id];
      const window = entry.window === 'inherit' ? (forecast.period === 'weekend' ? 'weekend' : 'day') : entry.window;
      const dates = windowDates(window, date);
      const timeline = [];
      for (let day = tomorrow; day <= dates[dates.length - 1]; day = addDays(day, 1)) {
        const weekDay = weekday(day);
        const useTomorrow = window === 'day' || (day === tomorrow && day < dates[0]);
        const needs = useTomorrow ? daily : weekDay === 6 ? sat : weekDay === 0 ? sun : daily;
        timeline.push({date: day, need: needs[product.id]});
      }
      const {sorted, assigned} = allocate(entry.lots, timeline, date);
      const plan = {window, dates, need: 0, physical: total(entry), used: 0, shortage: 0, reservedBefore: 0,
        readyUsed: 0, frozenUsed: 0, days: [], thaw: [], priorThaw: []};
      timeline.forEach((row, index) => {
        const prior = row.date < dates[0];
        let used = 0;
        assigned[index].forEach((take, i) => {
          if (!take) return;
          const lot = sorted[i];
          used += take;
          if (lot.storage === 'frozen') {
            (prior ? plan.priorThaw : plan.thaw).push({lotId: lot.id, label: lot.label, qty: quantity(take),
              start: addDays(row.date, -lot.thawDays), use: row.date});
            if (!prior) plan.frozenUsed += take;
          } else if (!prior) plan.readyUsed += take;
        });
        if (prior) plan.reservedBefore += used;
        else {
          plan.need += row.need;
          plan.used += used;
          plan.shortage += row.need - used;
          plan.days.push({date: row.date, need: quantity(row.need), used: quantity(used), shortage: quantity(row.need - used)});
        }
      });
      for (const key of ['need', 'used', 'shortage', 'reservedBefore', 'readyUsed', 'frozenUsed']) plan[key] = quantity(plan[key]);
      result[product.id] = plan;
    }
    return result;
  }
  return Object.freeze({today, validDate, addDays, windowDates, init, setProduct, total, recount, startThaw, removeWaste, restoreWaste, restoreLegacyWaste, build});
})();

.inventory-link, .inventory-remove {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  padding: 5px 0;
  color: var(--green, #173e32);
  background: transparent;
  font: inherit;
  font-size: 12px;
  font-weight: 650;
  text-align: left;
  text-decoration: underline;
  text-underline-offset: 3px;
}
.inventory-hint {
  display: block;
  max-width: 24ch;
  color: var(--muted, #536659);
  font-size: 12px;
  line-height: 1.45;
  white-space: normal;
}
#inventory-lot-dialog {
  box-sizing: border-box;
  width: min(740px, calc(100% - 24px));
  max-width: 740px;
  max-height: min(92vh, 900px);
  max-height: min(92dvh, 900px);
  padding: 0;
  overflow: hidden;
  border: 1px solid var(--line, #dce4da);
  border-radius: 16px;
  background: #fff;
  color: var(--ink, #193a2f);
}
#inventory-lot-dialog::backdrop { background: rgb(14 35 27 / 46%); }
.inventory-form { display: flex; flex-direction: column; max-height: inherit; }
.inventory-header, .inventory-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 17px 24px;
}
.inventory-header { border-bottom: 1px solid var(--line, #dce4da); }
.inventory-header p, #inventory-lot-dialog .inventory-note, #inventory-lot-dialog .inventory-period-value {
  margin: 0;
  color: var(--muted, #536659);
  font-size: 13px;
  line-height: 1.5;
}
.inventory-header h2 { margin: 3px 0 0; font-size: 24px; overflow-wrap: anywhere; }
.inventory-close {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  border-radius: 50%;
  background: #f1f4ed;
  color: var(--ink);
  font-size: 25px;
}
.inventory-scroll { min-height: 0; overflow-y: auto; overscroll-behavior: contain; padding: 20px 24px; }
.inventory-scroll > section + section { margin-top: 24px; }
.inventory-window {
  display: grid;
  grid-template-columns: minmax(150px, 1fr) minmax(190px, 1.5fr);
  align-items: end;
  gap: 8px 20px;
  padding: 16px;
  border-radius: 10px;
  background: #eff4e9;
}
.inventory-scroll h3 { margin: 0 0 8px; color: var(--ink); font-size: 17px; }
.inventory-lots [data-lot-list] { display: grid; gap: 14px; margin: 12px 0; }
.inventory-lot { min-width: 0; margin: 0; padding: 12px 14px; border: 1px solid var(--line, #dce4da); border-radius: 10px; }
.inventory-lot legend { padding: 0 5px; font-size: 13px; font-weight: 750; }
.inventory-fields { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px 16px; }
.inventory-field { display: grid; align-content: end; gap: 4px; min-width: 0; }
.inventory-field > span { color: var(--ink); font-size: 13px; font-weight: 650; }
.inventory-field input, .inventory-field select {
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  height: 42px;
  padding: 7px 9px;
  border: 1px solid #c8d4c8;
  border-radius: 6px;
  background: #fff;
  color: var(--ink);
  font: inherit;
  text-align: left;
}
.inventory-field[hidden], #inventory-lot-dialog [hidden] { display: none; }
#inventory-lot-dialog .inventory-lot .inventory-note,
#inventory-lot-dialog [data-split-help] { margin-top: 9px; }
.inventory-remove { margin-top: 8px; }
.inventory-result { padding: 16px; background: #f6f8f2; border-radius: 10px; }
.inventory-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0,1fr));
  gap: 12px;
  margin: 14px 0;
}
.inventory-metrics div { min-width: 0; }
.inventory-metrics dt { color: var(--muted); font-size: 12px; }
.inventory-metrics dd { margin: 2px 0 0; font-weight: 750; font-variant-numeric: tabular-nums; }
.inventory-days { margin: 8px 0; }
.inventory-days summary { width: fit-content; cursor: pointer; color: var(--green); font-weight: 650; }
.inventory-days table { width: 100%; margin-top: 8px; font-size: 13px; border-collapse: collapse; }
.inventory-days th, .inventory-days td { padding: 7px 4px; font-size: inherit; text-align: right; white-space: normal; }
.inventory-days tr > :first-child { text-align: left; }
.inventory-footer {
  flex-wrap: wrap;
  flex-shrink: 0;
  justify-content: flex-end;
  gap: 8px;
  border-top: 1px solid var(--line);
  background: #fff;
}
#inventory-lot-dialog [data-lot-error] { flex-basis: 100%; margin: 0; color: #8b3522; font-weight: 650; }
.inventory-thaw {
  margin: 16px 0;
  padding: 16px 18px;
  border: 1px solid #cedac8;
  border-radius: 10px;
  background: #f5f8ee;
}
.inventory-thaw h3 { margin: 0 0 8px; font-size: 17px; }
.inventory-thaw ul { margin: 0; padding: 0; list-style: none; }
.inventory-thaw li { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 4px 18px; padding: 9px 0; overflow-wrap: anywhere; }
.inventory-thaw li + li { border-top: 1px solid var(--line); }
.inventory-thaw li span { display: block; color: var(--muted); font-size: 13px; }
.inventory-thaw li strong, .inventory-thaw li b { color: var(--ink); }
.inventory-thaw-action { align-self: center; }
#inventory-lot-dialog .inventory-lot-date {
  margin: 0 0 10px;
  color: var(--green);
  font-size: 13px;
  font-weight: 650;
}
@media (max-width: 550px) {
  #inventory-lot-dialog { width: calc(100% - 12px); max-height: 94vh; max-height: 94dvh; }
  .inventory-header, .inventory-footer, .inventory-scroll { padding: 11px 13px; }
  .inventory-window { grid-template-columns: 1fr; padding: 12px; }
  .inventory-fields { gap: 9px; }
  .inventory-field input, .inventory-field select { font-size: 16px; }
  .inventory-metrics { grid-template-columns: repeat(2, minmax(0,1fr)); gap: 8px; }
  .inventory-lot, .inventory-result, .inventory-thaw { padding: 11px; }
  .inventory-days table { table-layout: fixed; }
  .inventory-days table th:first-child { width: 34%; }
  .inventory-days th, .inventory-days td { padding: 6px 2px; overflow-wrap: anywhere; }
}
@media print {
  .inventory-link, .inventory-thaw-action { display: none; }
  .inventory-thaw li { break-inside: avoid; }
}

